grid[-1]=[3,3,3,3,2,3,3,3,3,3,3,3,3,3,3,1,1]
H,W=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  col=grid[r][c]
  if col==3 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c));pts=[]
  while q:
   x,y=q.pop();pts.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    z=(x+dx,y+dy)
    if 0<=z[0]<H and 0<=z[1]<W and z not in seen and grid[z[0]][z[1]]==col:
     seen.add(z);q.append(z)
  comps.append((col,pts))
def norm(pts):
 mr=min(x for x,y in pts);mc=min(y for x,y in pts)
 return frozenset((x-mr,y-mc) for x,y in pts)
for i,(co,pts) in enumerate(comps): print(i,co,len(pts),(min(x for x,y in pts),min(y for x,y in pts),max(x for x,y in pts),max(y for x,y in pts)), sorted(pts), norm(pts))
